from tools.course_compiler_demo.production_question_packs.strength_of_materials.completion_300 import audit_completion,build_completion_bank
def test_strength_of_materials_completion_300():
 b,s=build_completion_bank();assert len(b.candidates)==100==s.validated;assert len({x["request"]["generation_family_id"] for x in b.candidates})==10;assert {x["request"]["difficulty"] for x in b.candidates}=={"introductory","intermediate","advanced"};assert all(x["request"]["parameters"]["thickness"]>0 and x["request"]["parameters"]["length"]>0 for x in b.candidates);assert audit_completion()["status"]=="PASS"
